import { quoteIdent } from '../kit/sql'
import { ARCHIVE_SCHEMA, SQL_TYPES, STAGING_SCHEMA, schemaOf, TABLES, type TableSpec } from './spec'

/**
 * Renders `staging_cloud.sql`: drop and recreate both schemas, one raw table per spec. Types are
 * permissive; the only constraint is the primary key. `_loaded_at` / `_row_hash` are loader columns.
 * Column names such as "key" or "group" are reserved words, so every identifier is quoted.
 */
export function renderDdl(tables: readonly TableSpec[] = TABLES): string {
  const out: string[] = [
    '-- GENERATED by apps/api/src/migration/ddl/render.ts from ddl/spec.ts. Do not edit by hand:',
    '-- run `npm run staging:ddl -w @pp/api` (a test fails when this file and the spec differ).',
    '-- Raw mirror of the .cloud tables (BE-27, plan 14.3): permissive types, no constraints except the PK.',
    '-- Executed by `staging:load` (not by Prisma) inside one transaction.',
    '',
    `drop schema if exists ${quoteIdent(STAGING_SCHEMA)} cascade;`,
    `drop schema if exists ${quoteIdent(ARCHIVE_SCHEMA)} cascade;`,
    `create schema ${quoteIdent(STAGING_SCHEMA)};`,
    `create schema ${quoteIdent(ARCHIVE_SCHEMA)};`,
    '',
  ]
  for (const t of tables) {
    const cols = t.columns.map((c) => `  ${quoteIdent(c.name)} ${SQL_TYPES[c.type]}`)
    cols.push('  "_loaded_at" timestamptz default now()', '  "_row_hash" text')
    if (t.pk) cols.push(`  primary key (${quoteIdent(t.pk)})`)
    out.push(`create table ${quoteIdent(schemaOf(t))}.${quoteIdent(t.name)} (`, cols.join(',\n'), ');', '')
  }
  return out.join('\n')
}
